window.kbPageData["views/entry/k-71ef9e139ab9eee8"] = {"key":"entry/k-71ef9e139ab9eee8","state":{"route":"entry/k-71ef9e139ab9eee8"},"node":{"id":"k-71ef9e139ab9eee8","mode":"k","title":"公立医院编制动态调整","type":"制度与规则","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["公立医院编制动态调整机制"],"qs":["国考 2025 副省级 行测#16","国考 2025 地市级 行测#16"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":1,"reviewSet":"多题条目","independentCount":1,"directorySummary":"公立医院编制动态调整是根据医院的功能定位和医疗服务需求等情况，适时调整人员编制配置的机制。","review":{"title":"公立医院编制动态调整","type":"制度与规则","definition":"公立医院编制动态调整是根据医院的功能定位和医疗服务需求等情况，适时调整人员编制配置的机制。","explanation":"2024年《中共中央关于进一步全面深化改革、推进中国式现代化的决定》第（45）项将完善薪酬制度、建立编制动态调整机制一并列入以公益性为导向的公立医院改革。编制调整的方向取决于实际配置需求。","basis":"据关联原题和解析编释。","references":[],"domain":"公共管理","examFocus":{"国考 2025 副省级 行测#16":"区分深化医药卫生体制改革对医疗资源布局、基层服务和公立医院管理的要求，逐项核对改革措施。"}},"aspects":[{"title":"公立医院改革中的编制管理","uses":[{"unit":"Q1","role":"直接考查","use":"题干要求选出深化医药卫生体制改革中不恰当的举措。C项保留了完善薪酬制度的要求，却把编制动态调整写成严格限制、缩减编制数量。","evidence":"完善公立医院薪酬制度，严格限制、缩减编制数量","qids":["国考 2025 副省级 行测#16","国考 2025 地市级 行测#16"]}]}]},"questions":{"国考 2025 副省级 行测#16":{"paper":"国考 2025 副省级 行测","n":16,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",3],"asrc":["ff0b352b44d417525086.pdf",5],"card":"e82f74517510386ebadd3c0f","links":[{"id":"k-71ef9e139ab9eee8","role":"直接考查","why":"公立医院改革要求完善薪酬制度并建立编制动态调整机制，考查编制管理的具体方式。"}]},"国考 2025 地市级 行测#16":{"paper":"国考 2025 地市级 行测","n":16,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",3],"asrc":["8cece062c7c079b53130.pdf",5],"card":"8c1f047a8b64f18c52247462","links":[{"id":"k-71ef9e139ab9eee8","role":"直接考查","why":"《决定》要求公立医院在完善薪酬制度的同时建立编制动态调整机制，据此可判断缩减编制的说法。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-71ef9e139ab9eee8":[["国考 2025 副省级 行测#16","国考 2025 地市级 行测#16"]]}};
